\label{thm:farsummary}
 In each of the following, $G$ is a graph with Dirac operator $D$, $x,y,z$ are vertices, $e$ is an edge, $D'$ denotes the Dirac operator of $G - e$, and $D''$ denotes the Dirac operator of $G - z$.
 \begin{itemize}
  \item[(i)] For every positive integer $N$, there exists a choice of $G$, $D$, $x$, $y$, and $e$ such that the graph-theoretic distance from $e$ to each of $x$ and $y$ is at least $N$ and $d^{D'}(x,y) < d^{D}(x,y)$.
  \item[(ii)] For every positive integer $N > 1$ and $\eta > 0$, there exists a choice of $G$, $D$, $x$, $y$, and $z$ such that the distance from $z$ to each of $x$ and $y$ is $N$, $d^{D}(x,y) < \eta$, and $d^{D''}(x,y) = 1$.
  \item[(iii)] For every $\rho > 0$, there exists a choice of $G$, $D$, $x$, $y$, and $e$ such that the weighted distance from $e$ to each of $x$ and $y$ is $\rho$ and
  \[ d^{D'}(x,y) \leqslant \frac{11}{5} < \sqrt{5} \leqslant d^{D}(x,y).\]
 \end{itemize}

\label{prop:chain}
 Let $G$ be the path with four vertices, $1 - 2 - 3 - 4$, such that $w_{ij}$ denotes the weight of the edge $\{i,j\}$.  Then,
 \[ d^{D}(1,4) = \begin{cases}
                \frac{\sqrt{w_{12}^2 + w_{23}^2}\sqrt{w_{34}^2 + w_{23}^2}}{w_{23}}, & w_{23} > \sqrt{w_{12}w_{34}},\\
                w_{12} + w_{34}, & \text{ otherwise.}
               \end{cases}\]
In particular, if $w_{12} = w_{23} = w_{34} = 1$, then $d^{D}(1,4) = 2$.

\cite[Corollary 3.1.3]{HJ94}
 \label{lem:compression}
 For $S \subseteq \{1, \dots, n\}$, $\left\lVert M_S \right\rVert \leqslant \left\lVert M \right\rVert.$

\label{lem:Pf4}
 Let $n \geqslant 4$ be even and suppose $M = (m_{i,j}) = [A,D]$, where $A$ is a diagonal matrix and $D$ is the Dirac operator for an $n$-cycle.  Then,
 \[ \operatorname{Pf}(M) = m_{12}m_{34} \cdots m_{n-1,n} - m_{23}m_{45} \cdots m_{n,1}.\]

\label{prop:skew}
 Let $M \in M_{2r}(\mathbb{R})$ be a skew-symmetric matrix.
 \begin{itemize}
  \item[(i)] The nonzero eigenvalues of $M$ occur in pairs $\pm is_j$, where each $s_j$ is a singular value of $M$; in particular, each singular value $s_j$ has even multiplicity.
  \item[(ii)] Let $M = (m_{ij}) \in M_4(\mathbb{R})$, $F = F(M) = \sum_{i<j} m_{ij}^2$, and $\operatorname{Pf} = \operatorname{Pf}(M) = m_{12}m_{34} - m_{13}m_{24} + m_{14}m_{23}$.  Then, the following hold:
    \begin{itemize}
      \item[\textbullet] $\det M = \operatorname{Pf}(M)^2$,
      \item[\textbullet] the two singular values $s_1 \geqslant s_2$ each have multiplicity two and satisfy $s_1^2 + s_2^2 = F$ and $s_1s_2 = |\operatorname{Pf}|$,
      \item[\textbullet] the eigenvalues of $iM$ are $\pm \frac{1}{\sqrt{2}}\left(F \pm \sqrt{F^2 - 4\operatorname{Pf}^2} \right)^{1/2}$,
      \item[\textbullet] $\left\lVert M \right\rVert \leqslant 1 \iff F \leqslant 2 \text{ and } F \leqslant 1 + \operatorname{Pf}^2.$
    \end{itemize}
 \end{itemize}

In terms of weights, the weighted $4$-cycle with $d_{12} = 1/5$ and $d_{23} = d_{34} = d_{41} = 1$ corresponds to a cycle whose edges have weights $5$, $1$, $1$, $1$.  See Figure \ref{fig:main}.

