\label{lem:ineq}
 Let $\delta, P, Q \in \mathbb{R}$ with $P,Q \geqslant 0$.  Then,
 \[ \sqrt{\delta^2 + P^2} + \sqrt{\delta^2 + Q^2} \leqslant \frac{2}{\sqrt{3}}\sqrt{4\delta^2 + (P+Q)^2}.\]

\label{lem:pfaffsympoly}
 For every skew-symmetric $M \in M_n(\mathbb{R})$ and every $0 \leqslant k \leqslant r$, we have
 \[  \varepsilon_k(M) = \sum_{\substack{S \subseteq \{1, \dots, n\},\\ |S| = 2k}} \operatorname{Pf}(M_S)^2.\]

Recall the definition of the Pfaffian \eqref{eq:Pf}.  Now, fix $k$ and let $S \subseteq V$ with $|S| = 2k$.  Since $M$ is supported on $G$, the terms of \eqref{eq:Pf} for $N = M_S$ vanish unless every edge of $F$ is an edge of $G$, i.e., unless $F$ is a perfect matching of the induced subgraph $G[S]$.  If we denote by $\mathcal{P} \mathcal{M}(H)$ the set of all perfect matchings of a graph $H$,  \eqref{eq:Pf} becomes
\[ \operatorname{Pf}(M_S) = \sum_{F \in \mathcal{P} \mathcal{M}(G[S])} {\rm sgn}(F) \prod_{f \in F} m_f,\]
which equals $0$ when $G[S]$ has no perfect matching.  By hypothesis, no subset of $V$ induces more than one perfect matching, so, after squaring, we have
\begin{equation}
 \label{eq:Pf2}
 \operatorname{Pf}(M_S)^2 = \begin{cases}
               \prod_{f \in F} m_f^2, &\mathcal{P} \mathcal{M}(G[S]) = \{F\},\\
               0, &\text{ otherwise.}
              \end{cases}
\end{equation}
Combining \eqref{eq:Pf2} with Lemma \ref{lem:pfaffsympoly}, we have
\[ \varepsilon_k(M) = \sum_{\substack{S \subseteq \{1, \dots, n\},\\ |S| = 2k}} \operatorname{Pf}(M_S)^2 = \sum_{F} \prod_{f \in F} m_f^2,\]
 where the last sum is over the sets $F$ of $k$ pairwise disjoint edges of $G$.

\label{thm:odd}
 Let $n$ be odd, let $D$ be a Dirac operator on the $n$-cycle, let $e$ be any edge, and let $D'$ be obtained from $D$ by deleting $e$.  Every $A$ admissible for $D$ is also admissible for $D'$, and for any vertices $x$ and $y$,
 \[ d^{D'}(x,y) \geqslant d^D(x,y).\]

\label{prop:reduction}
 Let $n = 2r,$ let $D$ be any Dirac operator on the $n$-cycle, let $e = \{1,2\}$, let $A$ be admissible for $D$ with $a_1 - a_2 = d^{D}(1,2)$, let $M = (m_{i,j}) = [A,D]$, and let $\mu_i = \max(-m_{i,i+1},0)$ for $2 \leqslant i \leqslant n$, where the subscripts are read modulo $n$, and set $\mu = (\mu_2, \dots, \mu_n)$.  Then, $m_{12} \geqslant 0$ and
 \[ d^{D}(1,2) \leqslant \left\lVert L(\mu) \right\rVert d^{D'}(1,2).\]

\label{thm:2mod4}
 Let $n = 2r$, where $r$ is odd.  Let $D$ be a Dirac operator on an $n$-cycle, $e$ be any edge, and $D'$ the Dirac operator obtained by deleting $e$.  For any vertices $x$ and $y$,
 \[ d^{D'}(x,y) \geqslant d^{D}(x,y). \]

\label{thm:0mod4}
 Let $n \geqslant 4$ be divisible by $4$.  There exists a choice of weights for the $n$-cycle such that, if $D$ denotes the Dirac operator of the $n$-cycle, $e$ is the edge $\{1,2\}$, and $D'$ is the Dirac operator obtained by deleting $e$, then
 \[ d^{D'}(1,2) < d^{D}(1,2).\]

\label{cor:nonincident}
 There exists a weighted graph $G^+$ with Dirac operator $D^+$, edge $e$, and vertices $x,y$ not incident with $e$ such that, if $D''$ is the Dirac operator of $G^+ - e$, we have
 \[ d^{D^+}(x,y) > d^{D''}(x,y).\]

\label{cor:far}
 For every positive integer $N$, there exists a weighted graph $G^+$ with Dirac operator $D^+$, edge $e$, and vertices $x,y$ at graph-theoretic distance at least $N$ from $e$ such that, if $D''$ is the Dirac operator of $G^+ - e$, we have
 \[ d^{D^+}(x,y) > d^{D''}(x,y).\]

\label{lem:blowup}
 Let $H$ be a finite simple graph with vertices $h_0, \dots, h_r$ and Dirac entries $C_{ij} \geqslant 0$, and let $k_0, \dots, k_r$ be positive integers.  Let $G = H[k_0, \dots, k_r]$ be the graph with vertex set $\bigsqcup_{i=0}^r L_i$, where $|L_i| = k_i$ for each $i$ in which $L_i$ and $L_j$ are completely joined whenever $h_i \sim h_j$, every such edge has Dirac entry $C_{ij}$, and with no edges inside $L_i$ or between $L_i$ and $L_j$ when $h_i \not\sim h_j$; let $G$ have Dirac operator $D$.  Let $\tilde{H}$ be the graph $H$ with Dirac operator $\tilde{C}$ having entries $\tilde{C}_{ij} = \sqrt{k_i k_j} C_{ij}$.  If two of the $L_i$ are singletons, say $L_p = \{x\}$ and $L_{p'} = \{y\}$, then
 \[ d^{D}(x,y) = d^{\tilde{C}}(h_p, h_{p'}).\]

\label{thm:nonlocal}
 Let $q \geqslant 1$ and $k \geqslant 1$.  Let $G = G_{q,k}$ be the graph obtained from the path
 \[ x - A_1 - A_2 - \cdots - A_q - z - B_q - \cdots - B_1 - y\]
 by blowing up each $A_j$ and $B_j$ to $k$ vertices as in Lemma \ref{lem:blowup}, where each edge of the blow up graph has weight $1$, and by further adjoining the edge $\{x,y\}$ of weight $1$.  Then, if $D$ is the Dirac operator of $G$ and $V' = V(G)\backslash\{z\}$,
 \begin{itemize}
  \item[(i)] the graph-theoretic distance and the weighted distance from $z$ to each of $x,y$ equal $q+1$;
  \item[(ii)] $d^{D}(x,y) \leqslant \frac{4}{\sqrt{k}} + \frac{2(q-1)}{k}$;
  \item[(iii)] $d_{V'}^D(x,y) = 1$.
 \end{itemize}
In particular, for any $\rho > 0$ and $\eta > 0$, we may choose $q$ with $q+1 \geqslant \rho$ and then $k$ large enough that $d^{D}(x,y) < \eta$ while $d_{V'}^D(x,y) = 1$; that is, deletion of a single vertex at arbitrarily large graph-theoretic and weighted distance from $x$ and $y$ changes $d^{D}(x,y)$ by an arbitrarily large factor.

\label{thm:farweight}
 Let $W > 0$ and let $k \geqslant 400W^2$ be an integer.  Let $G = G(W,k)$ have vertices $x,y$, four further vertices $1,2,3,4$, and two independent sets $L_1$, $L_2$ of size $k$, with edges defined as follows:
 \begin{itemize}
  \item $x$ is joined to every vertex of $L_1$, and every vertex of $L_1$ is joined to $1$, all of weight $W$;
  \item $y$ is joined to every vertex of $L_2$, and every vertex of $L_2$ is joined to $2$, all of weight $W$;
  \item the vertices $\{1,2,3,4\}$ form a $4$-cycle $1 - 2 - 3 - 4 - 1$ with $w_{12} = 5$ and $w_{23} = w_{34} = w_{41} = 1$.
 \end{itemize}
 Let $e = \{1,2\}$.  Then, $e$ is incident to neither $x$ nor $y$, the vertex $1$ is at weighted distance $2W$ from $x$, the vertex $2$ is at weighted distance $2W$ from $y$, and, if $G$ has Dirac operator $D$ and $G - e$ has Dirac operator $D'$,
 \[ d^{D}(x,y) \geqslant \sqrt{5} > \frac{11}{5} \geqslant d^{D'}(x,y).\]
 In particular, taking $W = \rho/2$ and $k = \lceil 100 \rho^2 \rceil$, the deleted edge $e$ lies at weighted distance $\rho$ from both $x$ and $y$, and $\rho$ may be arbitrarily large.
